function LeadWebhooksCard() {
  const [leads, setLeads] = useState([]);
  const [config, setConfig] = useState(null);
  const [copied, setCopied] = useState('');
  const { user } = useAuth();
  const origin = window.location.origin;
  const tid = user?.tenant_id || '';
  const hooks = [
    { key: 'facebook', label: 'فيسبوك Lead Ads', url: `${origin}/api/webhooks/facebook-leads/${tid}`, color: 'bg-blue-100 text-blue-700' },
    { key: 'tiktok', label: 'تيك توك Lead Generation', url: `${origin}/api/webhooks/tiktok-leads/${tid}`, color: 'bg-pink-100 text-pink-700' },
  ];
  const copy = (text, key) => {
    navigator.clipboard.writeText(text);
    setCopied(key);
    setTimeout(() => setCopied(''), 1500);
  };
  useEffect(() => {
    apiClient.get('/webhooks/config').then(r => setConfig(r.data)).catch(() => {});
    apiClient.get('/webhooks/leads?limit=10').then(r => setLeads(r.data || [])).catch(() => {});
  }, []);
  return (
    <Card>
      <CardHeader className="pb-3">
        <CardTitle className="text-base">Webhooks العملاء المحتملون (فيسبوك / تيك توك)</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {hooks.map(h => (
          <div key={h.key} className="space-y-1">
            <div className="flex items-center gap-2">
              <Badge className={h.color}>{h.label}</Badge>
              {h.key === 'facebook' && config && (
                <Badge variant="outline">{config.facebook_app_secret_set ? 'HMAC مُفعّل' : 'HMAC غير مضبوط (وضع التطوير)'}</Badge>
              )}
              {h.key === 'tiktok' && config && (
                <Badge variant="outline">{config.tiktok_app_secret_set ? 'HMAC مُفعّل' : 'HMAC غير مضبوط (وضع التطوير)'}</Badge>
              )}
            </div>
            <div className="flex items-center gap-2">
              <code className="flex-1 text-xs bg-muted p-2 rounded" dir="ltr">{h.url}</code>
              <Button variant="ghost" size="icon" onClick={() => copy(h.url, h.key)}>
                {copied === h.key ? <CheckCircle2 className="w-4 h-4 text-green-600" /> : <Copy className="w-4 h-4" />}
              </Button>
            </div>
          </div>
        ))}

        {/* p95: step-by-step setup guides */}
        <div className="space-y-2 border-t pt-3" data-testid="webhook-guide">
          <p className="text-sm font-semibold">📖 خطوات الإعداد</p>
          <details className="border rounded-lg p-3 bg-blue-50/40" data-testid="guide-facebook">
            <summary className="cursor-pointer font-semibold text-sm text-blue-800">فيسبوك Lead Ads — خطوة بخطوة</summary>
            <ol className="list-decimal mr-5 mt-2 space-y-1.5 text-sm text-muted-foreground">
              <li>ادخل إلى <code dir="ltr">developers.facebook.com</code> وأنشئ تطبيقاً (نوع Business) ثم أضف منتج <b>Webhooks</b> من لوحة التطبيق.</li>
              <li>في قائمة Webhooks اختر <b>Page</b> واضغط «Subscribe to this object»: الصق <b>رابط فيسبوك أعلاه</b> في خانة Callback URL، وفي خانة Verify Token ضع <b>الرمز الظاهر أسفل هذه البطاقة</b>، ثم اضغط «تحقق وحفظ».</li>
              <li>من اشتراكات الصفحة فعّل الحقل <code dir="ltr">leadgen</code> (Subscribe) للصفحة التي تجمع العملاء.</li>
              <li>احفظ <b>Page Access Token</b> في تكامل فيسبوك (من شبكة القنوات أعلاه ← فيسبوك) بصلاحية <code dir="ltr">leads_retrieval</code> — سيجلب النظام بيانات كل عميل تلقائياً عبر Graph API فور وصول الإشعار، <b>دون أي وسيط</b>. (بدون التوكن تصل الإشعارات لكن تُتخطّى لعدم وجود بيانات).</li>
              <li>للأمان: انسخ <b>App Secret</b> من إعدادات التطبيق ← الإعدادات الأساسية، وأضفه في الخادم باسم <code dir="ltr">FB_APP_SECRET</code> ليُفعَّل تحقق التوقيع <code dir="ltr">X-Hub-Signature-256</code>.</li>
              <li>جرّب من أداة <b>Lead Ads Testing Tool</b> في ميتا — يصل العميل إلى قائمة «آخر العملاء المحتملين» ويُسجَّل زبوناً جديداً تلقائياً مع إشعار.</li>
            </ol>
          </details>
          <details className="border rounded-lg p-3 bg-pink-50/40" data-testid="guide-tiktok">
            <summary className="cursor-pointer font-semibold text-sm text-pink-800">تيك توك Lead Generation — خطوة بخطوة</summary>
            <ol className="list-decimal mr-5 mt-2 space-y-1.5 text-sm text-muted-foreground">
              <li>من <b>TikTok Ads Manager</b> أنشئ حملة هدفها <b>Lead Generation</b> وصمّم نموذجاً فورياً (Instant Form).</li>
              <li>في إعدادات النموذج ← قسم <b>CRM / Webhook</b> اختر «Custom Webhook» والصق <b>رابط تيك توك أعلاه</b>.</li>
              <li>تيك توك يرسل بيانات النموذج مباشرةً (الاسم والهاتف ضمن الحمولة) — لا حاجة لوسيط.</li>
              <li>للأمان: أضف سرّ تطبيق تيك توك في الخادم باسم <code dir="ltr">TIKTOK_APP_SECRET</code> ليُفعَّل تحقق التوقيع <code dir="ltr">X-Tt-Signature</code>.</li>
              <li>أرسل <b>Test Lead</b> من لوحة تيك توك — سيظهر في «آخر العملاء المحتملين» خلال ثوانٍ ويُسجَّل زبوناً تلقائياً.</li>
            </ol>
          </details>
          <p className="text-xs text-muted-foreground">متغيرات الأمان تُضاف في ملف <code dir="ltr">backend.env</code> على الخادم ثم يُعاد تشغيل الباك إند. بدونها يعمل الويبهوك في وضع التطوير (بدون تحقق من التوقيع).</p>
        </div>

        {config && (
          <div className="text-xs text-muted-foreground space-y-1 border-t pt-3">
            <p>رمز التحقق (Verify Token) لفيسبوك: <code dir="ltr">{config.facebook_verify_token || 'غير مضبوط — عيّن FB_VERIFY_TOKEN'}</code></p>
            <p>{config.hmac_note} — المتغيرات: <code dir="ltr">FB_APP_SECRET</code> / <code dir="ltr">TIKTOK_APP_SECRET</code></p>
          </div>
        )}
        {leads.length > 0 && (
          <div className="border-t pt-3">
            <p className="text-sm font-semibold mb-2">آخر العملاء المحتملين ({leads.length})</p>
            <div className="space-y-1">
              {leads.map(l => (
                <div key={l.id} className="flex items-center justify-between text-sm p-2 rounded border bg-muted/30">
                  <div className="flex items-center gap-2">
                    <Badge className={l.source === 'facebook' ? 'bg-blue-100 text-blue-700' : 'bg-pink-100 text-pink-700'}>{l.source}</Badge>
                    <span>{l.name || '—'}</span>
                  </div>
                  <div className="flex items-center gap-3 text-muted-foreground">
                    <span dir="ltr">{l.phone}</span>
                    <span>{(l.created_at || '').slice(0, 10)}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

function WhatsAppTemplatesCard() {
  const [templates, setTemplates] = useState([]);
  const [showAll, setShowAll] = useState(false);
  useEffect(() => {
    apiClient.get('/whatsapp/templates').then(r => setTemplates(r.data || [])).catch(() => {});
  }, []);
  if (!templates.length) return null;
  const shown = showAll ? templates : templates.slice(0, 3);
  return (
    <Card>
      <CardHeader className="pb-3">
        <CardTitle className="text-base">قوالب رسائل واتساب ({templates.length})</CardTitle>
      </CardHeader>
      <CardContent className="space-y-2">
        {shown.map(t => (
          <div key={t.id} className="p-3 rounded-lg border bg-muted/30">
            <div className="flex items-center justify-between mb-1">
              <span className="font-semibold text-sm">{t.name}</span>
              {t.category && <Badge variant="outline">{t.category}</Badge>}
            </div>
            <p className="text-sm text-muted-foreground whitespace-pre-line">{t.body}</p>
          </div>
        ))}
        {templates.length > 3 && (
          <Button variant="ghost" size="sm" onClick={() => setShowAll(!showAll)}>
            {showAll ? 'عرض أقل' : `عرض الكل (${templates.length})`}
          </Button>
        )}
      </CardContent>
    </Card>
  );
}

export default function EcomChannelsPage() {
  const { user } = useAuth();
  const [integrations, setIntegrations] = useState([]);
  const [loading, setLoading] = useState(true);
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState({ channel: 'shopify', name: '', credentials: {}, is_active: true, return_fee: '' });
  const [saving, setSaving] = useState(false);
  const navigate = useNavigate();  // p288: meta channels connect via hub

  const load = async () => {
    setLoading(true);
    try {
      const res = await apiClient.get('/ecom/integrations');
      setIntegrations(res.data.items || []);
    } catch (err) {
      toast.error(err?.response?.data?.detail || 'فشل تحميل القنوات');
    } finally {
      setLoading(false);
    }
  };
  useEffect(() => { load(); }, []);

  const openCreate = (channel) => {
    if (['whatsapp', 'facebook', 'messenger', 'instagram'].includes(channel)) {  // p288: المفاتيح من مركز التكاملات
      navigate('/integrations');
      return;
    }
    setEditing(null);
    setForm({ channel, name: CHANNELS[channel]?.labelAr || channel, credentials: {}, is_active: true, return_fee: '' });
    setOpen(true);
  };

  const openEdit = (integration) => {
    setEditing(integration);
    setForm({
      channel: integration.channel,
      name: integration.name,
      credentials: {},   // empty inputs — leave blank to keep existing
      is_active: integration.is_active,
      return_fee: integration.return_fee ?? '',
    });
    setOpen(true);
  };

  const submit = async () => {
    if (!form.name.trim()) { toast.error('اسم التكامل مطلوب'); return; }
    setSaving(true);
    try {
      if (editing) {
        const payload = { name: form.name, is_active: form.is_active };
        // Only send credentials fields the user actually typed.
        const cleanCreds = Object.fromEntries(
          Object.entries(form.credentials).filter(([, v]) => v && String(v).trim())
        );
        if (Object.keys(cleanCreds).length > 0) payload.credentials = cleanCreds;
        if (CHANNELS[form.channel]?.kind === 'shipping' && form.return_fee !== '') payload.return_fee = Number(form.return_fee) || 0;  // p59
        await apiClient.put(`/ecom/integrations/${editing.id}`, payload);
        toast.success('تم تحديث التكامل');
      } else {
        await apiClient.post('/ecom/integrations', form);
        toast.success('تم ربط القناة بنجاح');
      }
      setOpen(false);
      load();
    } catch (err) {
      toast.error(err?.response?.data?.detail || 'فشل الحفظ');
    } finally {
      setSaving(false);
    }
  };

  const testConnection = async (id) => {
    try {
      const res = await apiClient.post(`/ecom/integrations/${id}/test`);
      toast.success(res.data.message || 'الاتصال يعمل');
    } catch (err) {
      toast.error(err?.response?.data?.detail || 'فشل الاختبار');
    }
  };

  const remove = async (integration) => {
    if (!window.confirm(`هل تريد حذف تكامل "${integration.name}"؟`)) return;
    try {
      await apiClient.delete(`/ecom/integrations/${integration.id}`);
      toast.success('تم الحذف');
      load();
    } catch (err) {
      toast.error('فشل الحذف');
    }
  };

  const schema = CREDENTIAL_SCHEMA[form.channel] || [];

  // p94: courier integrations are managed in /ecom-hub/shipping — hide them here
  const salesIntegrations = integrations.filter(i => CHANNELS[i.channel]?.kind !== 'shipping');

  return (
    <>
      <div className="space-y-6 p-4 md:p-6" dir="rtl" data-testid="ecom-channels-page">
        <div className="flex items-center justify-between flex-wrap gap-3">
          <div>
            <Link to="/ecom-hub" className="text-xs text-muted-foreground hover:text-foreground inline-flex items-center gap-1">
              <ArrowRight className="w-3 h-3" /> العودة لصندوق الطلبات
            </Link>
            <h1 className="text-2xl md:text-3xl font-bold mt-1 flex items-center gap-2">
              <Link2 className="w-7 h-7 text-emerald-600" />
              قنوات البيع
            </h1>
            <p className="text-sm text-muted-foreground mt-1">
              اربط متاجرك ووسائل التواصل لمزامنة الطلبات تلقائياً.
            </p>
          </div>
          <Button variant="outline" onClick={load}>
            <RefreshCcw className={`w-4 h-4 ml-1 ${loading ? 'animate-spin' : ''}`} />
            تحديث
          </Button>
        </div>

        {/* Mock-mode banner */}
        <div className="bg-amber-50 border border-amber-200 p-3 rounded-lg flex items-start gap-2 text-sm">
          <AlertTriangle className="w-5 h-5 text-amber-600 mt-0.5 flex-shrink-0" />
          <div>
            <div className="font-semibold text-amber-900">جميع القنوات في وضع المحاكاة (P1)</div>
            <div className="text-amber-800">
              يمكنك حفظ بيانات الربط الآن، ولكن المزامنة الفعلية مع Webhooks ستُفعَّل في المرحلة P2. مفاتيحك مخزَّنة بأمان ومُعدَّة للاستخدام.
            </div>
          </div>
        </div>

        {/* Available channels grid */}
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-base">قنوات متاحة للربط</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
              {SUPPORTED_CHANNELS.map(key => {
                const meta = CHANNELS[key];
                if (!meta) return null;   // safety — channel not in frontend catalogue
                const connectedCount = integrations.filter(i => i.channel === key).length;
                return (
                  <button
                    key={key}
                    onClick={() => openCreate(key)}
                    className={`p-4 rounded-lg border-2 ${meta.color} hover:scale-105 transition-transform text-center space-y-1`}
                    data-testid={`connect-channel-${key}`}
                  >
                    <div className="text-3xl">{meta.icon}</div>
                    <div className="font-semibold">{meta.labelAr}</div>
                    {connectedCount > 0 ? (
                      <Badge className="bg-emerald-200 text-emerald-900 text-xs">
                        <CheckCircle2 className="w-3 h-3 ml-1" /> {connectedCount} مرتبط
                      </Badge>
                    ) : (
                      <div className="text-xs text-muted-foreground flex items-center justify-center gap-1">
                        <Plus className="w-3 h-3" /> ربط
                      </div>
                    )}
                  </button>
                );
              })}
            </div>
          </CardContent>
        </Card>

        {/* Connected integrations list */}
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-base">التكاملات المُعدَّة ({salesIntegrations.length})</CardTitle>
          </CardHeader>
          <CardContent>
            {loading ? (
              <div className="text-center py-8 text-muted-foreground">جارٍ التحميل...</div>
            ) : salesIntegrations.length === 0 ? (
              <div className="text-center py-8 text-muted-foreground">
                لا توجد قنوات مرتبطة بعد. اختر قناة من الأعلى لبدء الربط.
              </div>
            ) : (
              <div className="space-y-2">
                {salesIntegrations.map(i => {
                  const meta = CHANNELS[i.channel] || CHANNELS.manual;
                  return (
                    <div key={i.id} className="flex items-center justify-between p-3 border rounded-lg hover:bg-muted/20">
                      <div className="flex items-center gap-3">
                        <span className="text-2xl">{meta.icon}</span>
                        <div>
                          <div className="font-semibold">{i.name}</div>
                          <div className="text-xs text-muted-foreground">
                            {meta.labelAr} • {i.mode === 'mock' ? '🧪 محاكاة' : '✅ فعّال'}
                            {i.last_sync_at && ` • آخر مزامنة: ${new Date(i.last_sync_at).toLocaleString('ar-DZ')}`}
                          </div>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <Badge variant={i.is_active ? 'default' : 'outline'}>
                          {i.is_active ? 'مُفعَّل' : 'مُوقَف'}
                        </Badge>
                        <Button size="sm" variant="ghost" onClick={() => testConnection(i.id)} data-testid={`test-integration-${i.id}`}>
                          <Zap className="w-4 h-4" />
                        </Button>
                        <Button size="sm" variant="ghost" onClick={() => openEdit(i)}>
                          تعديل
                        </Button>
                        <Button size="sm" variant="ghost" onClick={() => remove(i)} data-testid={`delete-integration-${i.id}`}>
                          <Trash2 className="w-4 h-4 text-rose-500" />
                        </Button>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Create/Edit dialog */}
      <AiStatusCard />

      <WhatsAppBusinessCard />

      <LeadWebhooksCard />

      <WhatsAppTemplatesCard />

      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent dir="rtl" className="max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              {CHANNELS[form.channel]?.icon} {editing ? 'تعديل' : 'ربط'} {CHANNELS[form.channel]?.labelAr}
            </DialogTitle>
            <DialogDescription>
              المفاتيح تُخزَّن مشفَّرة. اتركها فارغة عند التعديل للحفاظ على القيم الحالية.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-3 py-2">
            {/* Shopify webhook URL — shown when editing an existing Shopify integration */}
            {editing && form.channel === 'shopify' && user?.tenant_id && (
              <div className="bg-emerald-50 border border-emerald-300 rounded-lg p-3 space-y-1">
                <div className="text-xs font-semibold text-emerald-900">🪝 رابط الـ Webhook (انسخه إلى Shopify Admin → Notifications → Webhooks)</div>
                {(() => {
                  const url = `${window.location.origin}/api/ecom/webhooks/shopify/${user.tenant_id}/${editing.id}/orders`;
                  return (
                    <div className="flex items-center gap-1">
                      <code className="flex-1 text-[10px] bg-white border rounded px-2 py-1 break-all" data-testid="shopify-webhook-url">{url}</code>
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => { navigator.clipboard.writeText(url); toast.success('تم النسخ'); }}
                      >
                        <Copy className="w-3 h-3" />
                      </Button>
                    </div>
                  );
                })()}
                <div className="text-[10px] text-emerald-800">الموضوع: <code>orders/create</code> • التنسيق: JSON • تأكد من إدخال نفس Webhook Secret في الحقل أدناه.</div>
              </div>
            )}

            {!editing && (
              <div>
                <Label>القناة</Label>
                <Select value={form.channel} onValueChange={(v) => setForm({ ...form, channel: v, credentials: {}, name: CHANNELS[v]?.labelAr || v })}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {SUPPORTED_CHANNELS.map(k => (
                      <SelectItem key={k} value={k}>{CHANNELS[k].icon} {CHANNELS[k].labelAr}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}
            <div>
              <Label>الاسم المعروض</Label>
              <Input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} data-testid="integration-name-input" />
            </div>

            {/* p288: مفاتيح القنوات المغطاة بالمركز تُدار من مركز التكاملات فقط */}
            {['shopify', 'facebook', 'instagram', 'whatsapp', 'telegram'].includes(form.channel) ? (
              <div className="rounded-md border border-dashed p-3 text-sm bg-muted/30" data-testid="creds-hub-note">
                🔑 مفاتيح هذه القناة تُدار من{' '}
                <a href="/integrations" className="text-emerald-700 underline font-medium" data-testid="creds-hub-link">مركز التكاملات</a>
                {' '}— أدخلها هناك واضغط «حفظ واختبار» فتُفعَّل القناة تلقائياً. هنا يمكنك فقط تعديل الاسم والتفعيل.
              </div>
            ) : (
              schema.map(([key, label]) => (
                <div key={key}>
                  <Label>{label}</Label>
                  <Input
                    type="password"
                    placeholder={editing ? '••••••••  (اترك فارغاً للإبقاء)' : ''}
                    value={form.credentials[key] || ''}
                    onChange={e => setForm({ ...form, credentials: { ...form.credentials, [key]: e.target.value } })}
                    data-testid={`integration-cred-${key}`}
                  />
                </div>
              ))
            )}

            {CHANNELS[form.channel]?.kind === 'shipping' && (
              <div>
                <Label>سعر الإرجاع (دج)</Label>
                <Input
                  type="number" min="0" placeholder="مثال: 400"
                  value={form.return_fee}
                  onChange={e => setForm({ ...form, return_fee: e.target.value })}
                  data-testid="integration-return-fee"
                />
                <p className="text-xs text-muted-foreground mt-1">تُسجَّل كخسارة عند استرجاع الطلبات المشحونة عبر هذه الشركة</p>
              </div>
            )}

            <div className="flex items-center justify-between p-2 rounded border">
              <Label className="cursor-pointer">مُفعَّل</Label>
              <Switch
                checked={form.is_active}
                onCheckedChange={(v) => setForm({ ...form, is_active: v })}
                data-testid="integration-active-switch"
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setOpen(false)}>إلغاء</Button>
            <Button onClick={submit} disabled={saving} data-testid="integration-save-btn">
              {saving ? 'جارٍ الحفظ...' : 'حفظ'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

    </>
  );
}
